     "t": "math",
     "tex": "\\sum_{n=-\\infty}^{+\\infty} \\frac{\\sin(\\Omega_1 n)}{\\pi n} \\frac{\\sin(\\Omega_2 n)}{\\pi n} = \\frac{\\min(\\Omega_1, \\Omega_2)}{\\pi}"
